Here's an implementation of the Template Method design pattern for sorting algorithms in Python:

```python
from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    def sort(self, data):
        """Template method defining the sorting skeleton"""
        n = len(data)
        for i in range(n):
            for j in range(0, n-i-1):
                if self.compare(data[j], data[j+1]):
                    self.swap(data, j, j+1)

    @abstractmethod
    def compare(self, a, b):
        """Abstract method for comparison"""
        pass

    @abstractmethod
    def swap(self, data, i, j):
        """Abstract method for swapping elements"""
        pass

class BubbleSort(SortAlgorithm):
    def compare(self, a, b):
        return a > b

    def swap(self, data, i, j):
        data[i], data[j] = data[j], data[i]

class SelectionSort(SortAlgorithm):
    def compare(self, a, b):
        return a > b

    def swap(self, data, i, j):
        data[i], data[j] = data[j], data[i]

    def sort(self, data):
        """Overriding the template method for SelectionSort"""
        n = len(data)
        for i in range(n):
            min_idx = i
            for j in range(i+1, n):
                if self.compare(data[j], data[min_idx]):
                    min_idx = j
            self.swap(data, i, min_idx)

# Testing the implementation
if __name__ == "__main__":
    print("Testing sorting algorithms:")

    # Test with integers
    data_int = [64, 34, 25, 12, 22, 11, 90]
    print("\nOriginal array:", data_int)

    bubble = BubbleSort()
    bubble.sort(data_int.copy())
    print("Bubble Sort:", data_int)

    selection = SelectionSort()
    selection.sort(data_int.copy())
    print("Selection Sort:", data_int)

    # Test with strings
    data_str = ["banana", "apple", "pear", "orange", "grape"]
    print("\nOriginal array:", data_str)

    bubble.sort(data_str.copy())
    print("Bubble Sort:", data_str)

    selection.sort(data_str.copy())
    print("Selection Sort:", data_str)
